"""Product analytics dashboard: conversion statistics over customer sessions."""


def conversion_rate(events):
    """The share of sessions whose ``converted`` value is True."""
    if not events:
        return 0.0
    hits = sum(1 for event in events if event["converted"] is True)
    return hits / len(events)


def pooled_conversion_rate(groups):
    """Calculate a session-weighted conversion rate across all groups."""
    total_sessions = 0
    converted_sessions = 0
    for events in groups.values():
        total_sessions += len(events)
        converted_sessions += sum(1 for event in events if event["converted"] is True)
    if total_sessions == 0:
        return 0.0
    return converted_sessions / total_sessions


def conversions_in_window(daily_counts, days):
    """Sum the last ``days`` entries of daily counts (oldest first)."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])


def conversion_rate_by_group(groups):
    """Return conversion rates by group, with keys sorted by group name."""
    return {
        name: (conversion_rate(groups[name]) if groups[name] else None)
        for name in sorted(groups)
    }


def longest_conversion_streak(daily_counts):
    """Return the longest run of entries greater than zero."""
    best = current = 0
    for count in daily_counts:
        if count > 0:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best

"""Product analytics dashboard: parsing and organizing session data."""


def parse_session_log(lines):
    """Parse session log lines according to SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        fields = stripped.split(",")
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected exactly three fields")

        id_, day, converted = (field.strip() for field in fields)
        try:
            day = int(day)
        except ValueError as error:
            raise ValueError(f"line {line_number}: day must be an integer") from error

        if converted == "1":
            converted = True
        elif converted == "0":
            converted = False
        elif converted == "":
            converted = None
        else:
            raise ValueError(f"line {line_number}: converted must be 1, 0, or empty")

        out.append({"id": id_, "day": day, "converted": converted})
    return out


def dedupe_sessions(events):
    """Keep the last record for each id, then sort by day and id."""
    latest = {}
    for event in events:
        latest[event["id"]] = event
    return sorted(latest.values(), key=lambda event: (event["day"], event["id"]))


def daily_conversion_counts(events, start_day, end_day):
    """Count converted sessions for each day in the inclusive range."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["converted"] is True:
            counts[day - start_day] += 1
    return counts

